import{_ as e,c as o,o as r,ah as i}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"Directory listing","description":"Directory listing","frontmatter":{"title":"Directory listing","description":"Directory listing","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/products/directory-listing.md","filePath":"zenith/products/directory-listing.md"}'),n={name:"zenith/products/directory-listing.md"};function a(s,t,l,d,p,c){return r(),o("div",null,[...t[0]||(t[0]=[i('<p>We have added a new <strong>Directory Listing</strong> feature to the <a href="/zenith/introduction/">Multivendor Marketplace</a> App for Shopify.</p><h2 id="purpose-of-the-feature" tabindex="-1">Purpose of the feature <a class="header-anchor" href="#purpose-of-the-feature" aria-label="Permalink to &quot;Purpose of the feature&quot;">​</a></h2><p>If you want your customers to get redirected to a separate URL after clicking on the <strong>Buy Now</strong> button, then this feature will help you.</p><p>Enabling this feature will replace the <strong>Add to Cart</strong> button with a <strong>Buy Now</strong> button that will redirect customers to the desired URL. The URL can be your seller&#39;s website or any other page where you want your customers to complete the checkout process.</p><p><strong>Note:</strong> Each product can have a separate redirecting URL. Also, this feature can only be applicable to normal products, i.e., will not work for digital products or any other kind of product.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The admin needs to configure the following feature by visiting:</p><p><strong>Multivendor Marketplace Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Products Configuration</strong></p><p>On this page, you&#39;ll have the option to enable this feature. Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Configuration-Admin-2-1200x566.png" alt="Configuration-Admin-2"></p><p>Enable this feature &amp; enter the button name. Save the changes.</p><p>Once done, you&#39;ll need to add a code to the product template of your store&#39;s theme. The code is available in the note section below the directory listing button (refer to the image provided above).</p><p><strong>Instructions</strong>: Copy the below-given code &amp; paste it in the &#39;<strong>product.liquid</strong>&#39; or &#39;<strong>product-template.liquid</strong>&#39; file. The code needs to be added just above the <strong>Add to Cart</strong> button.</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {% </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;wk-directory-listing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><p><strong>NOTE</strong>:- In case you are using <strong><a href="https://www.shopify.com/partners/blog/shopify-online-store" target="_blank" rel="noreferrer">Online store 2.0</a></strong> (Example- Dawn), you need to add the codes to <strong>product.json</strong> &gt;&gt; <strong>sections/main-product.liquid</strong> file**😗*</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {% </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;wk-directory-listing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><h2 id="how-to-find-product-template-files" tabindex="-1">How to find product template files? <a class="header-anchor" href="#how-to-find-product-template-files" aria-label="Permalink to &quot;How to find product template files?&quot;">​</a></h2><p>You can edit the code for your theme:</p><ol><li>From your Shopify admin, go to <strong>Online Store</strong> &gt; <strong>Themes</strong>.</li><li>Click <strong>Actions</strong> &gt; <strong>Edit code</strong>.</li><li>Further, search for &#39;<strong>product.liquid</strong>&#39; template &amp; paste the code.</li></ol><p>Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/multivendor-marketplace-4-Edit-Debut-Shopify-1200x597.png" alt="multivendor-marketplace-4-Edit-Debut-Shopify"></p><p>If you are having trouble while updating the codes, let us know by emailing at <strong><a href="mailto:shopify@webkul.com" target="_blank" rel="noreferrer">shopify@webkul.com</a></strong> or creating a ticket for the same at <a href="https://webkul.uvdesk.com/" target="_blank" rel="noreferrer"><strong>Webkul UV Desk</strong></a>. We’ll do it for you!</p><h2 id="adding-directory-listing-product" tabindex="-1">Adding Directory Listing Product <a class="header-anchor" href="#adding-directory-listing-product" aria-label="Permalink to &quot;Adding Directory Listing Product&quot;">​</a></h2><p>Both admin and seller can add a directory listing product by following these steps:</p><p>Visit <strong>Multivendor Marketplace Admin/Seller Panel</strong> &gt; <strong>Products</strong> &gt; <strong>Product Listing</strong> &gt; <strong>Add Product</strong></p><p>(Instructions are shown with seller panel images whereas, the method to add a directory listing product is the same for admin as well.)</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Product-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x564.png" alt="Product-Seller-•-Multivendor-MarketPlace"></p><p>On the add product form, choose the product as <strong>Directory Listing Product</strong>. Further, on the right side, you&#39;ll have a section to enter directory listing details.<br> Here, enter the URL of the webpage to which you want to redirect your customers to make the purchase of this particular product. Save the changes once done!</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Add-Product-Seller-%E2%80%A2-Multivendor-MarketPlace-1200x909.png" alt="Add-Product-Seller-•-Multivendor-MarketPlace"></p><p>The product will have a <strong>directory listing button</strong> instead of a normal <strong>Add to Cart</strong> <strong>button</strong>. Clicking on the button, the customers will be redirected to the configured URL.</p><p>Example: For the product below, we have added the Webkul Blog link to the Buy Now button. <a href="https://multivendor-marketplace-4.myshopify.com/products/bright-red-purse-with-gold-detailing" target="_blank" rel="noreferrer">Try it yourself!</a></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/collage-1.png" alt="collage-1"></p>',32)])])}const u=e(n,[["render",a]]);export{h as __pageData,u as default};
